window.docContents[186].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Uniqueness-of-Types":{"contents":"\n\nAnother nice property of the STLC is that types are unique: a\ngiven term (in a given context) has at most one type.theorem unique_types (Γ : Context) (e : Tm) (τ τ' : Ty)\n    (h : <{ ~Γ ⊢ ~e ⦂ ~τ }>) (h' : <{ ~Γ ⊢ ~e ⦂ ~τ' }>) : τ = τ' := by\n  solution!\n    induction h generalizing τ' with\n    | var _ _ _ hx =>\n      cases h' with\n      | var _ _ _ hx' =>\n        rw [hx] at hx'\n        injection hx'\n    | abs _ _ τ₁ _ _ _ ih =>\n      cases h' with\n      | abs _ _ τ₁' _ _ hb' =>\n        have heq : τ₁ = τ₁' := by\n          apply ih\n          exact hb'\n        rw [heq]\n    | app _ _ _ _ _ _ _ ih₁ _ =>\n      cases h' with\n      | app _ _ _ _ _ hf' _ =>\n        have harrow := ih₁ _ hf'\n        injection harrow\n    | tru => cases h' with | tru => rfl\n    | fls => cases h' with | fls => rfl\n    | ite _ _ _ _ _ _ _ _ _ ih₂ _ =>\n      cases h' with\n      | ite _ _ _ _ _ _ h₂' _ =>\n        apply ih₂\n        exact h₂'\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC","header":"6.5. Uniqueness of Types","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Uniqueness-of-Types"}});